// An original deterministic fixture generated by this test, not a downloaded
// movie. Payload and metadata transfer are between two local sessions only.
// The production session may still perform its ordinary DHT bootstrap.
#include "AsanTorrent.h"
#include <libtorrent/add_torrent_params.hpp>
#include <libtorrent/create_torrent.hpp>
#include <libtorrent/file_storage.hpp>
#include <libtorrent/hasher.hpp>
#include <libtorrent/magnet_uri.hpp>
#include <libtorrent/session.hpp>
#include <libtorrent/session_params.hpp>
#include <libtorrent/settings_pack.hpp>
#include <libtorrent/torrent_info.hpp>
#include <libtorrent/torrent_status.hpp>
#include <atomic>
#include <chrono>
#include <cstdlib>
#include <filesystem>
#include <fstream>
#include <functional>
#include <iostream>
#include <iterator>
#include <memory>
#include <stdexcept>
#include <string>
#include <thread>
#include <vector>

namespace fs = std::filesystem;
namespace lt = libtorrent;
using namespace std::chrono_literals;
namespace {
constexpr char const* uuid = "9f6206b3-ddbd-4a47-9444-d3238ac7400b";
void check(bool condition, std::string const& message) { if (!condition) throw std::runtime_error(message); }
std::string json(char* raw, bool allowError = false) {
    check(raw != nullptr, "Native returned a null JSON string");
    std::string out(raw);
    asan_torrent_free_string(raw);
    if (!allowError) check(out.find("\"error\":") == std::string::npos, out);
    return out;
}
bool has(std::string const& text, char const* field) { return text.find(field) != std::string::npos; }
void eventually(std::function<bool()> condition, std::chrono::seconds timeout, char const* message) {
    auto const deadline = std::chrono::steady_clock::now() + timeout;
    while (std::chrono::steady_clock::now() < deadline) {
        if (condition()) return;
        std::this_thread::sleep_for(50ms);
    }
    throw std::runtime_error(message);
}
std::vector<char> bytes(std::size_t count) {
    std::vector<char> out(count);
    std::uint32_t state = 0x12345678;
    for (char& value : out) { state ^= state << 13; state ^= state >> 17; state ^= state << 5; value = static_cast<char>(state & 255); }
    return out;
}
void write(fs::path const& path, std::vector<char> const& value) {
    fs::create_directories(path.parent_path());
    std::ofstream out(path, std::ios::binary);
    out.write(value.data(), static_cast<std::streamsize>(value.size()));
    check(bool(out), "Cannot write generated test fixture");
}
std::vector<char> read(fs::path const& path) {
    std::ifstream in(path, std::ios::binary);
    return {std::istreambuf_iterator<char>(in), std::istreambuf_iterator<char>()};
}
std::string sha256(std::vector<char> const& data) {
    lt::hasher256 hash(data.data(), static_cast<int>(data.size()));
    auto const digest = hash.final().to_string();
    static char const hex[] = "0123456789abcdef";
    std::string result;
    for (unsigned char c : digest) { result += hex[c >> 4]; result += hex[c & 15]; }
    return result;
}
struct Watchdog {
    std::atomic_bool finished{false};
    std::thread thread;
    Watchdog() : thread([this] {
        auto const deadline = std::chrono::steady_clock::now() + 55s;
        while (!finished.load()) {
            if (std::chrono::steady_clock::now() > deadline) { std::cerr << "Native test exceeded 55 seconds\n"; std::_Exit(124); }
            std::this_thread::sleep_for(100ms);
        }
    }) {}
    ~Watchdog() { finished.store(true); thread.join(); }
};
struct TempRoot {
    fs::path path;
    TempRoot() {
        auto pattern = (fs::temp_directory_path() / "asan-native-torrent-XXXXXX").string();
        std::vector<char> buffer(pattern.begin(), pattern.end()); buffer.push_back('\0');
        char* actual = ::mkdtemp(buffer.data());
        check(actual != nullptr, "Cannot create exclusive test directory");
        path = actual;
    }
    ~TempRoot() { std::error_code ignored; fs::remove_all(path, ignored); }
};
using Native = std::unique_ptr<void, decltype(&asan_torrent_destroy)>;
Native native(fs::path const& root) {
    Native handle(asan_torrent_create(root.c_str()), asan_torrent_destroy);
    check(bool(handle), "Real torrent engine creation failed");
    return handle;
}
}
int main() try {
    Watchdog watchdog;
    TempRoot temporary;
    auto const seedPath = temporary.path / "seed";
    auto const cachePath = temporary.path / "downloads";
    auto const ownFile = bytes(512 * 1024);
    auto const unwantedFile = bytes(128 * 1024);
    write(seedPath / "fixture" / "clip.mp4", ownFile);
    write(seedPath / "fixture" / "unwanted.bin", unwantedFile);
    write(temporary.path / "outside.bin", ownFile);

    lt::file_storage storage;
    storage.add_file("fixture/clip.mp4", static_cast<std::int64_t>(ownFile.size()));
    storage.add_file("fixture/unwanted.bin", static_cast<std::int64_t>(unwantedFile.size()));
    lt::create_torrent creator(storage, 16 * 1024, lt::create_torrent::v1_only);
    creator.set_priv(true);
    lt::set_piece_hashes(creator, seedPath.string());
    auto const torrentBytes = creator.generate_buf();
    auto info = std::make_shared<lt::torrent_info>(lt::span<char const>(torrentBytes), lt::from_span);
    int selectedIndex = -1;
    for (auto index : info->files().file_range()) if (info->files().file_path(index) == "fixture/clip.mp4") selectedIndex = static_cast<int>(index);
    check(selectedIndex >= 0, "Generated fixture is missing its selected file");

    lt::settings_pack settings;
    settings.set_str(lt::settings_pack::listen_interfaces, "127.0.0.1:0");
    settings.set_bool(lt::settings_pack::enable_dht, false);
    settings.set_bool(lt::settings_pack::enable_lsd, false);
    settings.set_bool(lt::settings_pack::enable_upnp, false);
    settings.set_bool(lt::settings_pack::enable_natpmp, false);
    settings.set_bool(lt::settings_pack::allow_multiple_connections_per_ip, true);
    settings.set_int(lt::settings_pack::stop_tracker_timeout, 0);
    lt::session seed{lt::session_params(settings)};
    lt::add_torrent_params params;
    params.ti = info;
    params.save_path = seedPath.string();
    params.flags &= ~(lt::torrent_flags::paused | lt::torrent_flags::auto_managed);
    auto const seedTorrent = seed.add_torrent(params);
    eventually([&] { return seed.listen_port() != 0 && seedTorrent.status().is_seeding; }, 10s, "Local seed did not verify its generated pieces");
    auto const magnet = lt::make_magnet_uri(*info) + "&x.pe=127.0.0.1:" + std::to_string(seed.listen_port());

    auto engine = native(cachePath);
    auto const unsafeID = json(asan_torrent_add(engine.get(), "../../outside", magnet.c_str()), true);
    check(has(unsafeID, "\"error\":"), "Traversal identifier was accepted");
    auto const invalidMagnet = json(asan_torrent_add(engine.get(), uuid, "https://example.invalid/fixture.torrent"), true);
    check(has(invalidMagnet, "\"error\":"), "Non-magnet input was accepted");
    json(asan_torrent_add(engine.get(), uuid, magnet.c_str()));
    std::string state;
    eventually([&] { state = json(asan_torrent_snapshot(engine.get(), uuid)); return has(state, "\"hasMetadata\":true"); }, 10s, "Magnet metadata was not fetched from the localhost seed");
    std::this_thread::sleep_for(300ms);
    state = json(asan_torrent_snapshot(engine.get(), uuid));
    check(has(state, "\"selectedIndex\":null") && has(state, "\"isVerifiedComplete\":false"), "Metadata-only torrent was marked complete");
    auto const downloadedPath = cachePath / uuid / "fixture" / "clip.mp4";
    auto const unwantedPath = cachePath / uuid / "fixture" / "unwanted.bin";
    check(!fs::exists(downloadedPath) || fs::file_size(downloadedPath) == 0, "Payload downloaded before explicit file selection");
    check(!fs::exists(unwantedPath) || fs::file_size(unwantedPath) == 0, "Unselected payload downloaded during metadata lookup");
    check(has(json(asan_torrent_command(engine.get(), uuid, "select", 9999), true), "\"error\":"), "Out-of-range file selection was accepted");
    json(asan_torrent_command(engine.get(), uuid, "select", selectedIndex));
    json(asan_torrent_command(engine.get(), uuid, "pause", -1));
    json(asan_torrent_command(engine.get(), uuid, "resume", -1));
    eventually([&] { state = json(asan_torrent_snapshot(engine.get(), uuid)); return has(state, "\"isVerifiedComplete\":true"); }, 15s, "Selected file did not reach hash-verified completion");
    check(has(state, "\"isPaused\":true"), "Completed torrent was not paused");
    check(read(downloadedPath) == ownFile, "Downloaded bytes differ from generated fixture");
    check(sha256(read(downloadedPath)) == sha256(ownFile), "Downloaded SHA-256 differs");
    check(!fs::exists(unwantedPath) || fs::file_size(unwantedPath) == 0, "Unselected file was downloaded");

    // Recreate the C ABI engine against the same cache. The ordinary magnet
    // metadata path must recheck existing pieces, never trust a saved byte count.
    engine.reset();
    engine = native(cachePath);
    json(asan_torrent_add(engine.get(), uuid, magnet.c_str()));
    eventually([&] { state = json(asan_torrent_snapshot(engine.get(), uuid)); return has(state, "\"hasMetadata\":true"); }, 8s, "Metadata did not restore after engine restart");
    check(has(state, "\"isVerifiedComplete\":false"), "Restarted torrent bypassed explicit selection");
    json(asan_torrent_command(engine.get(), uuid, "select", selectedIndex));
    eventually([&] { state = json(asan_torrent_snapshot(engine.get(), uuid)); return has(state, "\"isVerifiedComplete\":true"); }, 8s, "Restart did not reverify existing pieces");
    check(read(downloadedPath) == ownFile, "Restart altered the verified payload");
    auto const removed = json(asan_torrent_command(engine.get(), uuid, "remove", -1));
    check(has(removed, "\"removed\":true"), "Native removal was not confirmed");
    check(!fs::exists(cachePath / uuid), "Owned download directory survived removal");
    check(read(temporary.path / "outside.bin") == ownFile, "Removal touched a file outside the download directory");
    std::cout << "{\"nativeTorrentTransfer\":\"passed\",\"bytes\":" << ownFile.size()
              << ",\"sha256\":\"" << sha256(ownFile)
              << "\",\"metadataGate\":true,\"selectedFileOnly\":true,\"restartRecheck\":true,\"pausedAfterCompletion\":true,\"containedRemoval\":true}\n";
    return 0;
} catch (std::exception const& error) {
    std::cerr << "Native torrent integration failed: " << error.what() << '\n';
    return 1;
}
